-- Canonical export recovered read-only from Staging migration history.
-- Version: 20260831064003; name: complete_network_match_footprints

create or replace function public.admin_update_network_match(p_response_id uuid,p_status text,p_note text default null) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_response public.network_match_responses%rowtype; v_request public.network_requests%rowtype; v_existing_status text; begin if v_actor is null or not exists(select 1 from public.admin_roles ar where ar.user_id=v_actor and ar.role_key in ('super_admin','admin','network_manager')) then raise exception 'insufficient_privilege'; end if; if p_status not in ('matched','needs_info','completed','rejected') then raise exception 'invalid_status'; end if; select * into v_response from public.network_match_responses where id=p_response_id for update; if not found then raise exception 'response_not_found'; end if; v_existing_status:=v_response.status::text; select * into v_request from public.network_requests where id=v_response.request_id; update public.network_match_responses set status=p_status::public.review_status,updated_at=now() where id=p_response_id; if p_status='matched' then update public.network_requests set status='matched',updated_at=now() where id=v_response.request_id and status not in ('completed','cancelled'); elsif p_status='completed' then update public.network_requests set status='completed',updated_at=now() where id=v_response.request_id; end if; insert into public.audit_logs(actor_user_id,actor_role,action,subject_type,subject_id,note) values(v_actor,'network_manager','network_match_'||p_status,'network_match_response',p_response_id::text,p_note); if p_status='completed' and v_existing_status<>'completed' then if not exists(select 1 from public.sharing_footprints where user_id=v_request.requester_user_id and source_type='network_match_response' and source_id=p_response_id) then insert into public.sharing_footprints(user_id,footprint_type,source_type,source_id,description) values(v_request.requester_user_id,'connection','network_match_response',p_response_id,'1% Network 媒合完成'); end if; if v_response.responder_user_id is not null and not exists(select 1 from public.sharing_footprints where user_id=v_response.responder_user_id and source_type='network_match_response' and source_id=p_response_id) then insert into public.sharing_footprints(user_id,footprint_type,source_type,source_id,description) values(v_response.responder_user_id,'connection','network_match_response',p_response_id,'1% Network 回應並完成媒合'); end if; end if; end; $$; revoke all on function public.admin_update_network_match(uuid,text,text) from public,anon; grant execute on function public.admin_update_network_match(uuid,text,text) to authenticated; create index if not exists idx_network_match_responses_request_status on public.network_match_responses(request_id,status); create index if not exists idx_user_notifications_recipient_unread_created on public.user_notifications(recipient_user_id,read_at,created_at desc);
